import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.BU4O3IzQ.js";const m=JSON.parse('{"title":"AI 动态 · 2026-08-06","description":"","frontmatter":{"title":"AI 动态 · 2026-08-06","date":"2026-08-06T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-06.md","filePath":"news/2026-08/ai-news-2026-08-06.md","lastUpdated":1786092171000}'),n={name:"news/2026-08/ai-news-2026-08-06.md"};function i(o,e,c,l,p,h){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-08-06" tabindex="-1">AI 动态 · 2026-08-06 <a class="header-anchor" href="#ai-动态-·-2026-08-06" aria-label="Permalink to &quot;AI 动态 · 2026-08-06&quot;">​</a></h1><blockquote><p>截至 2026-08-06。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="突发-jeff-dean离职创业-谷歌股价应声蒸发1-34万亿" tabindex="-1">突发，Jeff Dean离职创业！谷歌股价应声蒸发1.34万亿 <a class="header-anchor" href="#突发-jeff-dean离职创业-谷歌股价应声蒸发1-34万亿" aria-label="Permalink to &quot;突发，Jeff Dean离职创业！谷歌股价应声蒸发1.34万亿&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-06">2026-08-06</time></p><p>谷歌传奇工程师Jeff Dean宣布离职创业，与Sanjay Ghemawat、Quoc Le、Oriol Vinyals共同创办公益性AI公司Discovery Loop，聚焦机器学习、科学与工程自动化。同时，谷歌DeepMind CEO哈萨比斯卸任，转任董事长兼Alphabet首席科学家，由Koray Kavukcuoglu接任。消息公布后谷歌股价一度下跌超5%，市值蒸发逾万亿人民币。谷歌已入股新公司并成为其云合作伙伴。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/467196.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="超级算力枢纽远景乌兰察布星河基地投产-全球最大ai算力超级单体落地" tabindex="-1">超级算力枢纽远景乌兰察布星河基地投产，全球最大AI算力超级单体落地 <a class="header-anchor" href="#超级算力枢纽远景乌兰察布星河基地投产-全球最大ai算力超级单体落地" aria-label="Permalink to &quot;超级算力枢纽远景乌兰察布星河基地投产，全球最大AI算力超级单体落地&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-06">2026-08-06</time></p><p>远景科技集团宣布在乌兰察布建成全球最大AI算力超级单体，星河基地正式投产。该超级单体以12万平方米建筑体量、百万卡并行能力和百万P算力规模，成为全球Token产出能力最强的单体AI数据中心。园区总规划容量超2GW，采用超高比例绿电直连，将成为全国最大AI算力园区和Token工厂，为国产算力集群提供可复制的中国方案。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/467262.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="minimax-h3登顶开源社区第一-定义视频模型领域-斩杀线" tabindex="-1">MiniMax H3登顶开源社区第一，定义视频模型领域“斩杀线” <a class="header-anchor" href="#minimax-h3登顶开源社区第一-定义视频模型领域-斩杀线" aria-label="Permalink to &quot;MiniMax H3登顶开源社区第一，定义视频模型领域“斩杀线”&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-06">2026-08-06</time></p><p>MiniMax正式开源新一代通用多模态生成模型MiniMax H3，在Artificial Analysis视频编辑评测榜和Arena图生视频排行榜均位列全球第一，Hugging Face热度升至第一，超过DeepSeek V4 Flash。H3开源24小时内获超百家国内外合作伙伴适配接入，标志着中国开源AI从语言模型向视频模型延伸。杰富瑞、花旗均维持买入评级，MiniMax股价涨幅超10%。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/467270.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="artificial-analysis榜单-阿里qwen3-8-agentic能力得分全球第一" tabindex="-1">Artificial Analysis榜单：阿里Qwen3.8 Agentic能力得分全球第一 <a class="header-anchor" href="#artificial-analysis榜单-阿里qwen3-8-agentic能力得分全球第一" aria-label="Permalink to &quot;Artificial Analysis榜单：阿里Qwen3.8 Agentic能力得分全球第一&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-06">2026-08-06</time></p><p>Artificial Analysis公布新一期榜单，阿里Qwen3.8-Max在智能体能力（Agentic Index）排行榜中以55.4分超越Claude Opus5和GPT5.6，位列全球第一。该榜单衡量AI调用工具解决复杂问题的潜力，此前冠军长期被Claude、GPT垄断，中国模型最好成绩为Kimi K3的50.1分。此次夺冠标志着中国模型在Agentic能力上的重要突破。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/467444.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="aws-推出免费沙箱环境-可直接体验-workshop" tabindex="-1">AWS 推出免费沙箱环境，可直接体验 Workshop <a class="header-anchor" href="#aws-推出免费沙箱环境-可直接体验-workshop" aria-label="Permalink to &quot;AWS 推出免费沙箱环境，可直接体验 Workshop&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-06">2026-08-06</time></p><p><img src="https://static001.infoq.cn/resource/image/13/c4/13a3a8ff695813f3785ca3f52f18d2c4.jpg" alt="配图"></p><p>AWS Builder Center推出免费限时沙箱环境，开发者无需使用自己的AWS账号或绑定信用卡即可完成Workshop实践教程。每个沙箱可免费使用8小时，资源预配置通常在15分钟内就绪，到期自动清理。每位开发者每周最多创建一个沙箱，目前仅支持部分Workshop，涵盖Serverless API、VPC配置、容器部署及AI服务等主题，包括Claude Code on Amazon Bedrock。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/HtbD9e2YFkS3omFYgIyY?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="tirth8205-code-review-graph-本地优先的代码智能图谱" tabindex="-1">tirth8205/code-review-graph：本地优先的代码智能图谱 <a class="header-anchor" href="#tirth8205-code-review-graph-本地优先的代码智能图谱" aria-label="Permalink to &quot;tirth8205/code-review-graph：本地优先的代码智能图谱&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">tirth8205/code-review-graph</span><time datetime="2026-08-06">2026-08-06</time></p><p><img src="https://opengraph.githubassets.com/1/tirth8205/code-review-graph" alt="配图"></p><p>code-review-graph是一个本地优先的代码智能图谱项目，为MCP和CLI构建持久化的代码库地图，让AI编码工具只读取相关代码。项目宣称在代码审查和大型仓库工作流中实现了可基准测试的上下文缩减，有助于提升AI辅助开发在复杂代码库中的效率和准确性。</p><p class="news-entry-source"><a href="https://github.com/tirth8205/code-review-graph" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="mcp-迎来最大更新-重回上古时代-http" tabindex="-1">MCP 迎来最大更新：重回上古时代 HTTP <a class="header-anchor" href="#mcp-迎来最大更新-重回上古时代-http" aria-label="Permalink to &quot;MCP 迎来最大更新：重回上古时代 HTTP&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-06">2026-08-06</time></p><p><img src="https://static001.infoq.cn/resource/image/6b/yc/6b4783619c411e0ffe060b478b164yyc.jpg" alt="配图"></p><p>Model Context Protocol发布自上线以来最大更新：移除会话和初始化握手，每个请求独立携带完整上下文信息，使远程MCP服务器可像传统无状态HTTP服务一样操作，无需配置会话亲和性。官方称此举简化了MCP本身，解决了远程服务器水平扩展的长期痛点。但有开发者批评这是从WebSocket倒退，新旧协议共存阶段可能带来更高故障率。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/Lb94jI4ma9w0X9u0Ez6F?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="terraform-推出基于-hcl-的策略即代码框架-tfpolicy" tabindex="-1">Terraform 推出基于 HCL 的策略即代码框架 tfpolicy <a class="header-anchor" href="#terraform-推出基于-hcl-的策略即代码框架-tfpolicy" aria-label="Permalink to &quot;Terraform 推出基于 HCL 的策略即代码框架 tfpolicy&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-06">2026-08-06</time></p><p><img src="https://static001.infoq.cn/resource/image/99/d6/99e6819189cb1eec94467999602353d6.jpg" alt="配图"></p><p>HashiCorp发布tfpolicy，一套基于HCL的策略即代码框架，已在HCP Terraform中以公开Beta形式提供。tfpolicy将策略编写和执行直接集成到Terraform工作流，无需依赖Sentinel或OPA等独立策略工具。其深度集成支持部署前基于Plan的预期变更校验，也支持部署后依据资源实际运行状态执行治理，更贴近基础设施生命周期。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/ciBqgGa8fJIjYJdVaiq6?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="cloudflare-推出-meerkat-实现全球强一致性协调" tabindex="-1">Cloudflare 推出 Meerkat，实现全球强一致性协调 <a class="header-anchor" href="#cloudflare-推出-meerkat-实现全球强一致性协调" aria-label="Permalink to &quot;Cloudflare 推出 Meerkat，实现全球强一致性协调&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-06">2026-08-06</time></p><p><img src="https://static001.infoq.cn/resource/image/b0/3d/b03087b8156592c6bfb2b50e2cc5753d.jpg" alt="配图"></p><p>Cloudflare推出Meerkat，一个基于QuePaxa共识算法的全球一致性控制平面服务。与Raft不同，QuePaxa允许所有副本在不依赖领导者超时的情况下接受写入操作，避免广域网中领导者不可达时的可用性损失。Meerkat提供共识日志，支持事务型键值存储和租约管理等服务，预计将成为QuePaxa在全球范围内首次投入生产部署的案例。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/TzPsuyR3J7MlCA6vDwCx?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="claude-code之父-每半年清空一次claude-md、skills和hooks-模型自己会想办法" tabindex="-1">Claude Code之父：每半年清空一次claude.md、skills和hooks，模型自己会想办法 <a class="header-anchor" href="#claude-code之父-每半年清空一次claude-md、skills和hooks-模型自己会想办法" aria-label="Permalink to &quot;Claude Code之父：每半年清空一次claude.md、skills和hooks，模型自己会想办法&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-06">2026-08-06</time></p><p><img src="https://static001.infoq.cn/resource/image/53/2c/5376c0110d878a6f35c0594e55e3db2c.png" alt="配图"></p><p>Claude Code创始人Boris Cherny建议将模型视为“活着的生物”，每代模型性格不同，因此每隔六个月应删掉CLAUDE.md、Skills和Hooks，重新评估最新模型需要多少指令。Claude Code团队在Opus 5发布后一次删除了超过80%的系统提示词，通过消融实验判断内容价值。他还启动实验让Claude将Electron桌面应用重写为Swift，已连续运行两周多。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/hUTEb0LSzFUTyib1AJ4W?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="_2026-state-of-css-devs-surveys" tabindex="-1">2026 State of CSS, Devs Surveys <a class="header-anchor" href="#_2026-state-of-css-devs-surveys" aria-label="Permalink to &quot;2026 State of CSS, Devs Surveys&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">CSS-Tricks</span><time datetime="2026-08-06">2026-08-06</time></p><p><img src="https://i0.wp.com/css-tricks.com/wp-content/uploads/2026/08/state-of-css-2026-banner.png" alt="配图"></p><p>2026年State of CSS调查结果公布，CSS-Tricks位列Web平台资源使用率第三，仅次于MDN和Can I Use。调查显示CSS-Tricks的Guides和Almanac栏目获得广泛认可，团队近年投入大量精力完善这些资源。同时2026年State of Devs调查已开放，开发者可参与贡献数据。</p><p class="news-entry-source"><a href="https://css-tricks.com/2026-state-of-css-devs-surveys/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
